fn show_tabs(s: &str) -> String {
    s.lines()
        .map(|l| {
            let tabs = l.chars().take_while(|c| *c == '\t').count();
            let spaces = l.chars().skip(tabs).take_while(|c| *c == ' ').count();
            if tabs > 0 || spaces > 0 {
                format!("[{}t{}s]{}", tabs, spaces, l.trim_start())
            } else {
                l.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn run(src: &str, source_type: JsFileSource, indent: IndentStyle) {
    let tree = parse(
        src,
        source_type,
        JsParserOptions::default().with_parse_class_parameter_decorators(),
    );
    let options = JsFormatOptions::new(source_type)
        .with_indent_style(indent)
        .with_indent_width(4.into())
        .with_line_width(LineWidth::try_from(80).unwrap());
    let doc = format_node(options.clone(), &tree.syntax()).unwrap();
    let result = doc.print().unwrap();
    eprintln!("===== indent={:?} =====", indent);
    if indent.is_tab() {
        eprintln!("{}", show_tabs(result.as_code()));
    } else {
        eprintln!("{}", result.as_code());
    }
}

